(() => {
  const Z=window.Zucco,{platform:P,ui:U,ROUTES:R,escape:E,icon:I,btn:BT,badge:B}=Z;
  const settingsMenu=()=>`<nav class="settings-menu" aria-label="Settings categories">${[['general','Academy profile','building'],['preferences','Preferences','settings'],['notifications','Notifications','bell'],['access','Access & roles','shield']].map(([id,label,icon])=>`<button type="button" class="settings-tab ${P.settingsTab===id?'active':''}" data-action="ext-settings-tab:${id}">${I(icon)}${label}</button>`).join('')}</nav>`;
  function general(){const o=P.organization;return `<form id="organization-form" class="panel settings-form"><section class="settings-section"><h2>Academy profile</h2><p>These details identify your academy to students and staff.</p><div class="settings-grid">${U.field('Academy name','name',o.name,'text','required maxlength="70"')}${U.field('Contact phone','phone',o.phone,'tel','required')}${U.field('Contact email','email',o.email,'email','required')}${U.select('Default branch','branch',P.branches.map(b=>b.name),'Yunusobod')}</div></section><section class="settings-section"><h2>Regional settings</h2><p>Keep dates, money, and lessons consistent across branches.</p><div class="settings-grid">${U.select('Time zone','timezone',['Asia/Tashkent'],'Asia/Tashkent')}${U.select('Currency','currency',['UZS'],'UZS')}${U.select('Preferred language','language',['English','Uzbek'],o.language)}${U.field('Academic year','year','2026 — 2027','text','readonly')}</div></section><footer class="settings-save">${BT('Sign out','go:'+R.LOGIN)}<button type="submit" class="btn primary">${I('save')}Save changes</button></footer></form>`;}
  const toggle=(id,title,note,checked=true)=>`<label class="setting-toggle"><div class="grow"><h3>${title}</h3><p>${note}</p></div><span class="switch"><input type="checkbox" data-preference="${id}" ${P.preferences?.[id]===undefined?checked?'checked':'':P.preferences[id]?'checked':''} aria-label="${title}"><span class="switch-track"><span class="switch-thumb"></span></span></span></label>`;
  function preferences(){return `<section class="panel settings-form"><div class="settings-section"><h2>Workspace preferences</h2><p>Small choices that make daily operations more comfortable.</p>${toggle('compact','Compact tables','Keep more student and finance records in view.')}${toggle('sidebar','Start with a collapsed sidebar','Make more room for dense boards and tables.',false)}${toggle('receipts','Prepare payment receipts','Default new payments to prepare a receipt.')}</div><div class="settings-save">${BT('Save preferences','ext-save-preferences','save','primary')}</div></section>`;}
  function notifications(){return `<section class="panel settings-form"><div class="settings-section"><h2>Notification preferences</h2><p>Choose what should appear in your workspace notification center.</p>${toggle('leads','New lead activity','New conversations and trial lesson bookings.')}${toggle('finance','Finance updates','Payment entries, expenses, and outstanding balances.')}${toggle('payroll','Payroll review','Salary calculations that need your approval.')}${toggle('stock','Reward stock alerts','Items that are running low in the market.')}</div><div class="settings-save">${BT('Save notifications','ext-save-preferences','save','primary')}</div></section>`;}
  function access(){return U.panel('Roles & permissions',`<p class="caption">Assign access according to each team member’s responsibilities. Branch assignment controls where they work.</p><div class="conversion-details"><div class="detail-row"><span>Owner</span><strong>1 team member</strong></div><div class="detail-row"><span>Administrator</span><strong>1 team member</strong></div><div class="detail-row"><span>Teacher</span><strong>5 team members</strong></div><div class="detail-row"><span>Cashier</span><strong>1 team member</strong></div></div><div style="height:18px"></div>${BT('Manage roles & permissions','go:'+R.ROLES,'shield','primary')}`);}
  Z.renderers[R.SETTINGS]=()=>Z.heading('Settings','Make Zucco work the way your academy does.')+`<div class="settings-layout">${settingsMenu()}<div>${({general,preferences,notifications,access}[P.settingsTab]||general)()}</div></div>`;
  const modules=['Students','Leads','Groups & courses','Attendance','Payments','Expenses','Payroll','Staff & roles','Market & coins','SMS messages','Branches','Reports'];
  const roleDefault=(role,module,action)=>{if(role==='Owner')return true;if(role==='Administrator')return module!=='Staff & roles'||action==='View';if(role==='Teacher')return ['Students','Groups & courses','Attendance','Market & coins'].includes(module)&&['View','Create','Edit'].includes(action);return ['Students','Payments','Expenses','Reports'].includes(module)&&action!=='Delete';};
  Z.permissionValue=(role,module,action)=>P.roleOverrides[role+'|'+module+'|'+action]??roleDefault(role,module,action);
  Z.renderers[R.ROLES]=()=>Z.heading('Roles & permissions','Give the right people the right level of access.',BT('Back to settings','go:'+R.SETTINGS,'left')+BT('Save permissions','ext-save-roles','save','primary'))+
    `<div class="role-summary">${['Owner','Administrator','Teacher','Cashier'].map(role=>`<button type="button" class="role-pill ${role===P.selectedRole?'active':''}" data-action="ext-select-role:${role}"><strong>${role}</strong><span>${P.staff.filter(s=>s.role===role).length} team member${role==='Teacher'?'s':''}</span></button>`).join('')}</div>`+
    U.table([['Module',40],['View',15],['Create',15],['Edit',15],['Delete',15]],modules.map(module=>`<tr><td><span class="table-primary">${module}</span>${module==='Payments'?'<p class="table-secondary">Payment entry and student balances</p>':''}</td>${['View','Create','Edit','Delete'].map(action=>`<td><input class="permission-check" type="checkbox" data-permission="${P.selectedRole}|${module}|${action}" aria-label="${P.selectedRole}: ${action} ${module}" ${Z.permissionValue(P.selectedRole,module,action)?'checked':''} ${P.selectedRole==='Owner'?'disabled':''}></td>`).join('')}</tr>`).join(''),'','<span>Owner access is protected. Permission changes in this prototype remain local.</span>');
})();
